#!/bin/bash
# Загрузка карточек публикаций в core.paper_card (самодостаточно: SQL внутри).
# Агент на ВМ забирает ТОЛЬКО command.sh, поэтому все данные встроены.
export PGPASSFILE=/home/ubuntu/.pgpass
W=/tmp/pcwork; mkdir -p $W
PSQL="psql -h localhost -U wiki -d research_wiki -v ON_ERROR_STOP=1"

echo "=== 0. бэкап core перед изменением (правило обратимости) ==="
pg_dump -h localhost -U wiki -d research_wiki -n core -f /home/ubuntu/backup_core_pre_papercard.sql 2>&1 | head -3
ls -la /home/ubuntu/backup_core_pre_papercard.sql

echo "=== 1. схема ==="
