gunzip -c $W/load.gz > $W/load.sql
wc -l $W/load.sql
$PSQL -f $W/load.sql
echo "  данные загружены"

echo "=== 3. контроль ==="
$PSQL -tAc "SELECT 'всего карточек: ' || count(*) FROM core.paper_card"
$PSQL -tAc "SELECT 'авторы: ' || count(*) FROM core.paper_card WHERE authors <> ''"
$PSQL -tAc "SELECT 'год: ' || count(*) FROM core.paper_card WHERE year IS NOT NULL"
$PSQL -tAc "SELECT 'выводы: ' || count(*) FROM core.paper_card WHERE findings <> ''"
$PSQL -tAc "SELECT 'методы: ' || count(*) FROM core.paper_card WHERE cardinality(methods) > 0"
$PSQL -tAc "SELECT 'литература: ' || count(*) FROM core.paper_card WHERE n_references > 0"
$PSQL -tAc "SELECT 'файл: ' || count(*) FROM core.paper_card WHERE file_available"
$PSQL -tAc "SELECT 'presigned: ' || count(*) FROM core.paper_card WHERE presigned_url <> ''"
$PSQL -tAc "SELECT 'записей литературы: ' || sum(n_references) FROM core.paper_card"
echo "--- примеры ---"
$PSQL -tAc "SELECT paper_code || ' | ' || coalesce(year::text,'-') || ' | ' || left(coalesce(authors,''),38) || ' | refs=' || n_references FROM core.paper_card WHERE n_references > 30 LIMIT 4"
$PSQL -tAc "SELECT 'витрина: ' || count(*) FROM core.v_paper_card"
echo "=== ГОТОВО ==="
